using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Invoices.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Invoices.Commands.IssueInvoice;public sealed class IssueInvoiceCommandHandler(IInvoiceRepository repository,IApplicationDbContext db):IRequestHandler<IssueInvoiceCommand,Result<InvoiceDto>>{public async Task<Result<InvoiceDto>>Handle(IssueInvoiceCommand request,CancellationToken cancellationToken){var e=await repository.FindForUpdateAsync(request.Id,cancellationToken);if(e is null)return Result.Failure<InvoiceDto>(InvoiceErrors.NotFound);if(e.Status.ToString()!="Draft")return Result.Failure<InvoiceDto>(InvoiceErrors.NotDraft);e.Issue();await db.SaveChangesAsync(cancellationToken);return Result.Success(InvoiceDto.FromEntity(e));}}
